import pandas as pd

rooms = pd.DataFrame({
    'room_id': ['R101', 'R102', 'R103'],
    'area_m2': [78.0, 44.2, 18.5],
})
print(rooms)

def material_required(area_m2: float, allowance: float = 0.10) -> float:
    """Return required material area including a waste allowance."""
    return area_m2 * (1 + allowance)

print(material_required(44.2))
print(material_required(44.2, allowance=0.15))

def estimate_annual_energy_kwh(energy_kwh_m2_yr: pd.Series, area_m2: pd.Series) -> pd.Series:
    """Total annual energy use, in kWh/yr."""
    return (energy_kwh_m2_yr * area_m2).round(0)

rooms['energy_kwh_yr'] = estimate_annual_energy_kwh(rooms.energy_kwh_m2_yr, rooms.area_m2)
print(rooms[['room_id', 'area_m2', 'energy_kwh_yr']].head(3))
